import numpy as np
import pandas as pd

DATASET_PATH = 'chunks_csv/moran_global_2022_transport.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

df_transport = pd.read_csv(DATASET_PATH)
df_adj = pd.read_csv(ADJACENCY_PATH)

boroughs = df_transport['borough'].unique()
neighbor_dict = {borough: set() for borough in boroughs}

for _, row in df_adj.iterrows():
    boro = row['borough']
    neighbor = row['neighbor']
    neighbor_dict[boro].add(neighbor)
    neighbor_dict[neighbor].add(boro)

n = len(boroughs)
W = np.zeros((n, n))

for i in range(n):
    boro_i = boroughs[i]
    for j in range(n):
        if boroughs[j] in neighbor_dict[boro_i]:
            W[i][j] = 1

W_sum = W.sum()

x = df_transport['Transport_value'].values
mean_x = np.mean(x)

numerator = 0
for i in range(n):
    for j in range(n):
        if W[i][j] == 1:
            numerator += (x[i] - mean_x) * (x[j] - mean_x)

denominator = np.sum((x - mean_x)**2) * (W_sum / n)
observed_I = numerator / denominator

permutations = 500
count = 0

for _ in range(permutations):
    x_perm = np.random.permutation(x)
    numerator_perm = 0
    for i in range(n):
        for j in range(n):
            if W[i][j] == 1:
                numerator_perm += (x_perm[i] - mean_x) * (x_perm[j] - mean_x)
    denominator_perm = np.sum((x_perm - mean_x)**2) * (W_sum / n)
    I_perm = numerator_perm / denominator_perm
    if I_perm >= observed_I:
        count += 1

p_value = (count + 1) / (permutations + 1)

print(f"Global Moran's I: {observed_I}")
print(f"p-value: {p_value}")

if p_value < 0.05:
    print(f"FINAL ANSWER: CLUSTERED (statistical method = Global Moran's I, p = {p_value})")
else:
    print(f"FINAL ANSWER: NOT CLUSTERED (statistical method = Global Moran's I, p = {p_value})")
